slug: propertychanged-wrong-property-name
stack: dotnet
topic: ui-dotnet
level: middle
type: find-bug
grading: auto
tags: [inotifypropertychanged, data-binding, mvvm, callermembername]
code:
  language: csharp
  harness: statements
  source: |
    using System.ComponentModel;

    var vm = new PersonViewModel();
    vm.PropertyChanged += (_, e) => Console.WriteLine(e.PropertyName);
    vm.FirstName = "Ada";
    vm.LastName = "Lovelace";

    class PersonViewModel : INotifyPropertyChanged
    {
        private string firstName = "";
        private string lastName = "";

        public event PropertyChangedEventHandler PropertyChanged;

        public string FirstName
        {
            get => firstName;
            set
            {
                firstName = value;
                OnPropertyChanged("FirstName");
            }
        }

        public string LastName
        {
            get => lastName;
            set
            {
                lastName = value;
                OnPropertyChanged("FirstName");
            }
        }

        private void OnPropertyChanged(string propertyName) =>
            PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(propertyName));
    }
bugLineSets: [[31]]
fixedSource: |
  using System.ComponentModel;
  using System.Runtime.CompilerServices;

  var vm = new PersonViewModel();
  vm.PropertyChanged += (_, e) => Console.WriteLine(e.PropertyName);
  vm.FirstName = "Ada";
  vm.LastName = "Lovelace";

  class PersonViewModel : INotifyPropertyChanged
  {
      private string firstName = "";
      private string lastName = "";

      public event PropertyChangedEventHandler PropertyChanged;

      public string FirstName
      {
          get => firstName;
          set
          {
              firstName = value;
              OnPropertyChanged();
          }
      }

      public string LastName
      {
          get => lastName;
          set
          {
              lastName = value;
              OnPropertyChanged();
          }
      }

      // The compiler passes the name of the calling property.
      private void OnPropertyChanged([CallerMemberName] string propertyName = null) =>
          PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(propertyName));
  }
fixedExpect: { kind: output, value: "FirstName\nLastName" }
